import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract user from session token
app.use(async (req, res, next) => {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'No session' });
  try {
    const result = await pool.query(
      'SELECT user_id, role, org_id FROM sessions WHERE token = $1 AND expires_at > NOW()',
      [token]
    );
    if (result.rows.length === 0) return res.status(401).json({ error: 'Invalid session' });
    req.user = result.rows[0];
    next();
  } catch (e) {
    next(e);
  }
});

// Fetch documents - supports flexible filtering
app.get('/api/documents', async (req, res) => {
  try {
    const { category, sort_by, direction } = req.query;

    // Base query scoped to user's org
    let query = `SELECT id, title, category, created_at, org_id 
                 FROM documents WHERE org_id = $1`;
    const params = [req.user.org_id];

    if (category) {
      params.push(category);
      query += ` AND category = $${params.length}`;
    }

    // Sort - validated against allowlist
    const allowedSorts = ['created_at', 'title', 'category'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const dir = direction === 'ASC' ? 'ASC' : 'DESC';
    query += ` ORDER BY ${sortCol} ${dir} LIMIT 100`;

    const result = await pool.query(query, params);
    res.json({ documents: result.rows });
  } catch (e) {
    res.status(500).json({ error: 'Query failed', detail: e.message });
  }
});

// Export documents - generates CSV with user-controlled filename
app.get('/api/documents/export', async (req, res) => {
  try {
    const { format, filename } = req.query;

    const result = await pool.query(
      'SELECT id, title, category, created_at FROM documents WHERE org_id = $1',
      [req.user.org_id]
    );

    if (format === 'csv') {
      // User-supplied filename used in Content-Disposition header
      const exportName = filename || `export_${Date.now()}`;
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="${exportName}.csv"`);

      let csv = 'id,title,category,created_at\n';
      for (const row of result.rows) {
        csv += `${row.id},"${row.title}","${row.category}",${row.created_at}\n`;
      }
      res.send(csv);
    } else {
      res.json({ documents: result.rows });
    }
  } catch (e) {
    res.status(500).json({ error: 'Export failed' });
  }
});

// Search with raw text matching
app.get('/api/documents/search', async (req, res) => {
  try {
    const { q, include_archived } = req.query;
    if (!q || q.length < 2) return res.status(400).json({ error: 'Query too short' });

    // VULNERABLE: q is interpolated directly into the query
    const archiveClause = include_archived === 'true' ? '' : "AND archived = false";
    const query = `SELECT id, title, category, created_at FROM documents 
                   WHERE org_id = $1 ${archiveClause} 
                   AND (title ILIKE '%${q}%' OR category ILIKE '%${q}%')
                   LIMIT 50`;

    const result = await pool.query(query, [req.user.org_id]);
    res.json({ documents: result.rows });
  } catch (e) {
    res.status(500).json({ error: 'Search failed', detail: e.message });
  }
});

app.listen(3000, () => console.log('Document service running on :3000'));
